/**
 * @internal This type only exists until ADES-1980 is resolved and the series-overrides can directly
 *    be passed to the chart API. Then this type is no longer necessary for the conversion-utils.
 */
export interface _ChartColorToken {
    Default: string;
    Hover: string;
    Active: string;
}
/**
 * @internal This type only exists until ADES-1980 is resolved and the series-overrides can directly
 *    be passed to the chart API. Then this type is no longer necessary for the conversion-utils.
 */
export type _Color = _ChartColorToken | string;
/**
 * @internal This type only exists until ADES-1980 is resolved and the series-overrides can directly
 *    be passed to the chart API. Then this type is no longer necessary for the conversion-utils.
 */
export type _SeriesOverride = {
    color: _Color;
};
/**
 * @internal This type only exists until ADES-1980 is resolved and the series-overrides can directly
 *    be passed to the chart API. Then this type is no longer necessary for the conversion-utils.
 */
export type _SeriesOverrides = {
    seriesId: string | string[];
    override: _SeriesOverride;
}[];
